-- exmd2-12.hs: extended Minsky doubling (value x2, 12 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 2^12 = 4096.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x2
exmd (x, 0,    2) = exmd (  x,   0,    5)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=5): x -> y, x2
exmd (0, y,    5) = exmd (  0,   y,    8)
exmd (x, y,    5) = exmd (x-1,   y,    6)
exmd (x, y,    6) = exmd (  x, y+1,    7)
exmd (x, y,    7) = exmd (  x, y+1,    5)

-- Cycle 2 (pc=8): y -> x, x2
exmd (x, 0,    8) = exmd (  x,   0,   11)
exmd (x, y,    8) = exmd (  x, y-1,    9)
exmd (x, y,    9) = exmd (x+1,   y,   10)
exmd (x, y,   10) = exmd (x+1,   y,    8)

-- Cycle 3 (pc=11): x -> y, x2
exmd (0, y,   11) = exmd (  0,   y,   14)
exmd (x, y,   11) = exmd (x-1,   y,   12)
exmd (x, y,   12) = exmd (  x, y+1,   13)
exmd (x, y,   13) = exmd (  x, y+1,   11)

-- Cycle 4 (pc=14): y -> x, x2
exmd (x, 0,   14) = exmd (  x,   0,   17)
exmd (x, y,   14) = exmd (  x, y-1,   15)
exmd (x, y,   15) = exmd (x+1,   y,   16)
exmd (x, y,   16) = exmd (x+1,   y,   14)

-- Cycle 5 (pc=17): x -> y, x2
exmd (0, y,   17) = exmd (  0,   y,   20)
exmd (x, y,   17) = exmd (x-1,   y,   18)
exmd (x, y,   18) = exmd (  x, y+1,   19)
exmd (x, y,   19) = exmd (  x, y+1,   17)

-- Cycle 6 (pc=20): y -> x, x2
exmd (x, 0,   20) = exmd (  x,   0,   23)
exmd (x, y,   20) = exmd (  x, y-1,   21)
exmd (x, y,   21) = exmd (x+1,   y,   22)
exmd (x, y,   22) = exmd (x+1,   y,   20)

-- Cycle 7 (pc=23): x -> y, x2
exmd (0, y,   23) = exmd (  0,   y,   26)
exmd (x, y,   23) = exmd (x-1,   y,   24)
exmd (x, y,   24) = exmd (  x, y+1,   25)
exmd (x, y,   25) = exmd (  x, y+1,   23)

-- Cycle 8 (pc=26): y -> x, x2
exmd (x, 0,   26) = exmd (  x,   0,   29)
exmd (x, y,   26) = exmd (  x, y-1,   27)
exmd (x, y,   27) = exmd (x+1,   y,   28)
exmd (x, y,   28) = exmd (x+1,   y,   26)

-- Cycle 9 (pc=29): x -> y, x2
exmd (0, y,   29) = exmd (  0,   y,   32)
exmd (x, y,   29) = exmd (x-1,   y,   30)
exmd (x, y,   30) = exmd (  x, y+1,   31)
exmd (x, y,   31) = exmd (  x, y+1,   29)

-- Cycle 10 (pc=32): y -> x, x2
exmd (x, 0,   32) = exmd (  x,   0,   35)
exmd (x, y,   32) = exmd (  x, y-1,   33)
exmd (x, y,   33) = exmd (x+1,   y,   34)
exmd (x, y,   34) = exmd (x+1,   y,   32)

-- Cycle 11 (pc=35): x -> y, x2
exmd (0, y,   35) = exmd (  0,   y,   38)
exmd (x, y,   35) = exmd (x-1,   y,   36)
exmd (x, y,   36) = exmd (  x, y+1,   37)
exmd (x, y,   37) = exmd (  x, y+1,   35)

-- Drain (pc=38): DEC y to 0, then HALT
exmd (x, 0,   38) = (  x,   0,    1)
exmd (x, y,   38) = exmd (  x, y-1,   38)
